# fix: release_v1_0_5.md TODO-118 (cluster / blocked-cluster part). Null assignment draws
# for DesignFixedCluster and DesignFixedBlockedCluster are generated by one batched pass
# (block_ra_batch over clusters, expanded to subjects) instead of
# replicate(r, randomizr::cluster_ra / block_and_cluster_ra). Same law, NOT bit-identical
# to the old path under a seed (documented seed-pinned-draw change).

make_cluster_design_t118b = function(sizes, prob_T = 0.5, seed = 5L) {
	n = sum(sizes)
	X = data.frame(x = seq_len(n) / n, cl = factor(rep(seq_along(sizes), times = sizes)))
	d = DesignFixedCluster$new(n = n, response_type = "continuous", cluster_col = "cl", prob_T = prob_T, seed = seed)
	d$add_all_subjects_to_experiment(X)
	d$assign_w_to_all_subjects()
	list(d = d, cl = X$cl)
}

make_bcluster_design_t118b = function(prob_T = 0.5, seed = 5L) {
	# block a: 5 clusters, block b: 4 clusters, block c: 1 cluster; uneven cluster sizes
	sizes = c(2, 3, 1, 2, 2, 3, 2, 1, 4, 10)  # equal subject count (10) per block
	blk = rep(c("a", "a", "a", "a", "a", "b", "b", "b", "b", "c"), times = sizes)
	cl = factor(rep(seq_along(sizes), times = sizes))
	n = sum(sizes)
	X = data.frame(x = seq_len(n) / n, blk = factor(blk), cl = cl)
	d = DesignFixedBlockedCluster$new(n = n, response_type = "continuous", strata_cols = "blk",
		cluster_col = "cl", prob_T = prob_T, seed = seed)
	d$add_all_subjects_to_experiment(X)
	d$assign_w_to_all_subjects()
	list(d = d, cl = cl, blk = X$blk, clblk = c("a","a","a","a","a","b","b","b","b","c"))
}

test_that("DesignFixedCluster batched draws: whole clusters, exact counts, seed-reproducible, equals batch helper", {
	x = make_cluster_design_t118b(c(3, 2, 4, 1, 5, 2, 3))
	w = x$d$draw_ws_according_to_design(300L)
	expect_equal(dim(w), c(20L, 300L))
	expect_true(all(w %in% c(0, 1)))
	# within-cluster constant
	for (k in levels(x$cl)) expect_true(all(apply(w[x$cl == k, , drop = FALSE], 2, function(v) length(unique(v)) == 1L)))
	# treated clusters per draw: K = 7, prob .5 -> 3 or 4
	first = match(levels(x$cl), x$cl)
	ntc = colSums(w[first, , drop = FALSE])
	expect_true(all(ntc %in% c(3, 4)))
	expect_equal(mean(ntc == 4), 0.5, tolerance = 0.1)
	# reproducible by seed, and equal to the helper expanded to subjects
	expect_identical(w, x$d$draw_ws_according_to_design(300L))
	set.seed(5L)
	ref = block_ra_batch(rep(1L, 7L), 0.5, 300L)[as.integer(x$cl), , drop = FALSE]
	expect_equal(unname(w), unname(ref))
})

test_that("DesignFixedCluster batched draws match randomizr::cluster_ra in distribution", {
	skip_if_not_installed("randomizr")
	for (p in c(0.5, 0.3)) {
		x = make_cluster_design_t118b(c(3, 2, 4, 1, 5, 2, 3), prob_T = p)
		wb = x$d$draw_ws_according_to_design(3000L)
		set.seed(3)
		wr = replicate(1500L, as.numeric(as.character(randomizr::cluster_ra(clusters = as.character(x$cl), prob = p))))
		expect_equal(rowMeans(wb), rep(p, 20), tolerance = 0.04)
		expect_equal(rowMeans(wb), rowMeans(wr), tolerance = 0.06)
		first = match(levels(x$cl), x$cl)
		tb = table(factor(colSums(wb[first, ]), levels = 0:7)) / ncol(wb)
		tr = table(factor(colSums(wr[first, ]), levels = 0:7)) / ncol(wr)
		expect_lt(max(abs(tb - tr)), 0.06)
	}
})

test_that("DesignFixedBlockedCluster batched draws: whole clusters, exact counts per block, reproducible", {
	x = make_bcluster_design_t118b()
	w = x$d$draw_ws_according_to_design(300L)
	expect_equal(dim(w), c(30L, 300L))
	for (k in levels(x$cl)) expect_true(all(apply(w[x$cl == k, , drop = FALSE], 2, function(v) length(unique(v)) == 1L)))
	first = match(levels(x$cl), x$cl)
	wc = w[first, , drop = FALSE]
	clblk = x$clblk
	# block a: 5 clusters -> 2 or 3; block b: 4 clusters -> exactly 2; block c: 1 cluster -> 0/1 at p=.5
	ta = colSums(wc[clblk == "a", , drop = FALSE])
	expect_true(all(ta %in% c(2, 3)))
	expect_equal(mean(ta == 3), 0.5, tolerance = 0.1)
	expect_true(all(colSums(wc[clblk == "b", , drop = FALSE]) == 2))
	expect_equal(mean(wc[clblk == "c", ]), 0.5, tolerance = 0.1)
	expect_identical(w, x$d$draw_ws_according_to_design(300L))
})

test_that("DesignFixedBlockedCluster batched draws match randomizr::block_and_cluster_ra in distribution", {
	skip_if_not_installed("randomizr")
	x = make_bcluster_design_t118b()
	wb = x$d$draw_ws_according_to_design(3000L)
	set.seed(4)
	wr = replicate(1500L, as.numeric(as.character(randomizr::block_and_cluster_ra(
		blocks = as.character(x$blk), clusters = as.character(x$cl), prob = 0.5))))
	expect_equal(rowMeans(wb), rowMeans(wr), tolerance = 0.06)
	first = match(levels(x$cl), x$cl)
	for (b in c("a", "b", "c")) {
		idx = first[x$clblk == b]
		tb = table(factor(colSums(wb[idx, , drop = FALSE]), levels = 0:5)) / ncol(wb)
		tr = table(factor(colSums(wr[idx, , drop = FALSE]), levels = 0:5)) / ncol(wr)
		expect_lt(max(abs(tb - tr)), 0.06)
	}
})

test_that("DesignFixedBlockedCluster rejects clusters that span blocks", {
	n = 8
	X = data.frame(x = seq_len(n), blk = factor(rep(c("a", "b"), 4)), cl = factor(rep(1:4, each = 2)))
	d = DesignFixedBlockedCluster$new(n = n, response_type = "continuous", strata_cols = "blk", cluster_col = "cl", seed = 1L)
	d$add_all_subjects_to_experiment(X)
	expect_error(suppressWarnings(d$assign_w_to_all_subjects()))
})
